        private static char _nextToken[] = new char[(StackFIFOMemoryBuffer.StackSize <= 4096 ? 2 : 1)];
        private static int _foreachDepth = 1;

        public static Token GetToken(int index)
        {
            return (Token)_nextToken[index];
        }

        private static void PushToken(TokenType type, int index) => _nextToken[index] = type;

        public static int Depth
        {
            get => _foreachDepth;
        }

        private static readonly Dictionary<string, int> sourceLocator = new();

        public static void InitSourceLocator(string[] sources)
        {
            var names = sources.Where(s => s.StartsWith("class")).ToList();
            foreach (var name in names)
            {
                sourceLocator.Add(name, int.Parse(name.Substring(0, 2)));
            }
        }

        public static ISourceLocator GetSourceLocator() => sourceLocator;
